1	import { types as nodeTypes } from 'node:util';
2	
3	const NODE_TYPES = new Set(['trigger', 'form', 'condition', 'action', 'end']);
4	const FIELD_TYPES = new Set(['string', 'number', 'integer', 'boolean']);
5	const FORBIDDEN_SEGMENTS = new Set(['__proto__', 'prototype', 'constructor']);
6	const STRING_BOUNDS = new Set(['minLength', 'maxLength']);
7	const NUMBER_BOUNDS = new Set(['min', 'max']);
8	
9	function assertPlainObject(value, label) {
10	  if (!value || typeof value !== 'object' || Array.isArray(value)) {
11	    throw new TypeError(`${label} must be an object`);
12	  }
13	}
14	
15	function isUsableObject(value) {
16	  return value !== null && typeof value === 'object' && !Array.isArray(value);
17	}
18	
19	function valueMatchesType(value, type) {
20	  if (type === 'string') return typeof value === 'string';
21	  if (type === 'boolean') return typeof value === 'boolean';
22	  if (typeof value !== 'number') return false;
23	  if (type === 'number') return Number.isFinite(value);
24	  return Number.isInteger(value);
25	}
26	
27	function valueSatisfiesBounds(value, spec) {
28	  if (spec.type === 'string') {
29	    const length = [...value].length;
30	    if (spec.minLength !== undefined && length < spec.minLength) return false;
31	    if (spec.maxLength !== undefined && length > spec.maxLength) return false;
32	  } else if (spec.type === 'number' || spec.type === 'integer') {
33	    if (spec.min !== undefined && value < spec.min) return false;
34	    if (spec.max !== undefined && value > spec.max) return false;
35	  }
36	  return true;
37	}
38	
39	function compileFormSchema(node) {
40	  if (!Object.hasOwn(node, 'schema') || node.schema === undefined) return null;
41	  if (!isUsableObject(node.schema)) {
42	    throw new Error(`form node ${node.id}: schema must be an object`);
43	  }
44	  if (!Array.isArray(node.schema.fields)) {
45	    throw new Error(`form node ${node.id}: schema.fields must be an array`);
46	  }
47	
48	  const seenSegments = [];
49	  const compiled = [];
50	  node.schema.fields.forEach((field, index) => {
51	    const label = `form node ${node.id} field ${field && isUsableObject(field) && typeof field.path === 'string' && field.path ? field.path : `#${index}`}`;
52	    if (!isUsableObject(field)) {
53	      throw new Error(`${label}: field must be an object`);
54	    }
55	    if (typeof field.path !== 'string' || field.path.length === 0) {
56	      throw new Error(`form node ${node.id} field #${index}: path must be a non-empty string`);
57	    }
58	    const segments = field.path.split('.');
59	    if (segments.some(part => part.length === 0)) {
60	      throw new Error(`${label}: path must not contain empty segments`);
61	    }
62	    if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
63	      throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
64	    }
65	    for (const previous of seenSegments) {
66	      const shared = Math.min(previous.length, segments.length);
67	      let prefix = true;
68	      for (let i = 0; i < shared; i += 1) {
69	        if (previous[i] !== segments[i]) { prefix = false; break; }
70	      }
71	      if (prefix && previous.length === segments.length) {
72	        throw new Error(`${label}: duplicate field path`);
73	      }
74	      if (prefix) {
75	        throw new Error(`${label}: field paths must not be parent and child of each other`);
76	      }
77	    }
78	    seenSegments.push(segments);
79	
80	    if (!FIELD_TYPES.has(field.type)) {
81	      throw new Error(`${label}: unknown field type ${field.type}`);
82	    }
83	    const spec = { path: field.path, segments, type: field.type, required: false, hasDefault: false };
84	
85	    if (Object.hasOwn(field, 'required')) {
86	      if (typeof field.required !== 'boolean') {
87	        throw new Error(`${label}: required must be a boolean`);
88	      }
89	      spec.required = field.required;
90	    }
91	
92	    const applicableBounds = field.type === 'string' ? STRING_BOUNDS
93	      : (field.type === 'number' || field.type === 'integer') ? NUMBER_BOUNDS
94	      : new Set();
95	    for (const bound of ['minLength', 'maxLength', 'min', 'max']) {
96	      if (!Object.hasOwn(field, bound) || field[bound] === undefined) continue;
97	      if (!applicableBounds.has(bound)) {
98	        throw new Error(`${label}: ${bound} does not apply to ${field.type} fields`);
99	      }
100	      const value = field[bound];
101	      if (field.type === 'string') {
102	        if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
103	          throw new Error(`${label}: ${bound} must be a non-negative integer`);
104	        }
105	      } else if (typeof value !== 'number' || !Number.isFinite(value)) {
106	        throw new Error(`${label}: ${bound} must be a finite number`);
107	      }
108	      spec[bound] = value;
109	    }
110	    if (spec.minLength !== undefined && spec.maxLength !== undefined && spec.minLength > spec.maxLength) {
111	      throw new Error(`${label}: minLength must not be greater than maxLength`);
112	    }
113	    if (spec.min !== undefined && spec.max !== undefined && spec.min > spec.max) {
114	      throw new Error(`${label}: min must not be greater than max`);
115	    }
116	
117	    if (Object.hasOwn(field, 'default') && field.default !== undefined) {
118	      const fallback = field.default;
119	      if (!valueMatchesType(fallback, spec.type)) {
120	        throw new Error(`${label}: default value does not match field type ${spec.type}`);
121	      }
122	      if (!valueSatisfiesBounds(fallback, spec)) {
123	        throw new Error(`${label}: default value violates field constraints`);
124	      }
125	      spec.hasDefault = true;
126	      spec.default = fallback;
127	    }
128	
129	    compiled.push(spec);
130	  });
131	
132	  return compiled;
133	}
134	
135	const MAX_CONDITION_DEPTH = 32;
136	
137	function parsePathSegments(path, label) {
138	  if (typeof path !== 'string' || path.length === 0) {
139	    throw new Error(`${label}: path must be a non-empty string`);
140	  }
141	  const segments = path.split('.');
142	  if (segments.some(part => part.length === 0)) {
143	    throw new Error(`${label}: path must not contain empty segments`);
144	  }
145	  if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
146	    throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
147	  }
148	  return segments;
149	}
150	
151	function isComparableConstant(value) {
152	  return value === null || typeof value === 'string' || typeof value === 'boolean'
153	    || (typeof value === 'number' && Number.isFinite(value));
154	}
155	
156	function toComparableNumber(value) {
157	  // Objects and arrays never participate in numeric comparison, even though
158	  // Number([]) === 0; everything else uses JS numeric conversion.
159	  if (value !== null && typeof value === 'object') return null;
160	  const converted = Number(value);
161	  return Number.isFinite(converted) ? converted : null;
162	}
163	
164	// Validates an output reference of the shape
165	// `{ "nodeId": "risk-check", "path": "risk.score" }` (path optional). The
166	// reference itself must be a non-array object, nodeId must name an action
167	// node in this definition (matched as a whole string — dots are literal),
168	// and path, when present, follows the same segment rules as input paths.
169	function compileOutputReference(ref, nodes, label) {
170	  if (!isUsableObject(ref)) {
171	    throw new Error(`${label}: output reference must be a non-array object`);
172	  }
173	  if (typeof ref.nodeId !== 'string' || ref.nodeId.length === 0) {
174	    throw new Error(`${label}: nodeId must be a non-empty string naming an action node`);
175	  }
176	  const target = nodes.get(ref.nodeId);
177	  if (!target) {
178	    throw new Error(`${label}: nodeId "${ref.nodeId}" does not name a node in this workflow`);
179	  }
180	  if (target.type !== 'action') {
181	    throw new Error(`${label}: nodeId "${ref.nodeId}" must name an action node`);
182	  }
183	  let segments = [];
184	  if (Object.hasOwn(ref, 'path')) {
185	    segments = parsePathSegments(ref.path, `${label} path`);
186	  }
187	  return { nodeId: ref.nodeId, segments };
188	}
189	
190	// Walks every condition node (including untaken branches) and turns it into a
191	// pre-validated, pre-resolved structure. Any malformed condition throws with a
192	// node id and a `$`-style child position, before the workflow can execute.
193	function compileCondition(condition, nodes, nodeId, position = '$', depth = 1) {
194	  if (depth > MAX_CONDITION_DEPTH) {
195	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
196	  }
197	  if (!isUsableObject(condition)) {
198	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
199	  }
200	
201	  const comboKeys = [];
202	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
203	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
204	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
205	  if (comboKeys.length > 1) {
206	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
207	  }
208	
209	  const comparisonKeys = ['field', 'outputField', 'operator', 'value', 'valueField', 'valueOutputField'];
210	  const presentComparisonKeys = comparisonKeys.filter(key => Object.hasOwn(condition, key));
211	
212	  if (comboKeys.length === 1) {
213	    if (presentComparisonKeys.length > 0) {
214	      throw new Error(`condition node ${nodeId} at ${position}: ${comboKeys[0]} condition must not mix in field, outputField, operator, value, valueField or valueOutputField`);
215	    }
216	    const key = comboKeys[0];
217	    if (key === 'not') {
218	      return { kind: 'not', child: compileCondition(condition.not, nodes, nodeId, `${position}.not`, depth + 1) };
219	    }
220	    const childList = condition[key];
221	    if (!Array.isArray(childList)) {
222	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must be an array of conditions`);
223	    }
224	    if (childList.length === 0) {
225	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must not be empty`);
226	    }
227	    // A non-empty array may still carry length without a condition at every
228	    // slot: a child deleted through the JavaScript API can leave a hole, or
229	    // the array may have been allocated with gaps only. A missing slot is a
230	    // definition error at its own original index — it is never treated as
231	    // false, skipped over or filled in — so it is reported even when an
232	    // earlier sibling would already short-circuit the compound. Explicit
233	    // undefined/null entries are not holes: they remain present and fall
234	    // through to the ordinary "condition must be an object" rejection.
235	    const children = [];
236	    for (let index = 0; index < childList.length; index += 1) {
237	      if (!Object.hasOwn(childList, index)) {
238	        throw new Error(`condition node ${nodeId} at ${position}.${key}[${index}]: ${key}[${index}] is a missing child condition`);
239	      }
240	      children.push(
241	        compileCondition(childList[index], nodes, nodeId, `${position}.${key}[${index}]`, depth + 1));
242	    }
243	    return { kind: key, children };
244	  }
245	
246	  const where = `condition node ${nodeId} at ${position}`;
247	  const hasField = Object.hasOwn(condition, 'field');
248	  const hasOutputField = Object.hasOwn(condition, 'outputField');
249	  if ((!hasField && !hasOutputField) || !Object.hasOwn(condition, 'operator')) {
250	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
251	  }
252	  if (hasField && hasOutputField) {
253	    throw new Error(`${where}: condition must specify exactly one of field or outputField`);
254	  }
255	
256	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
257	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
258	  }
259	
260	  let left;
261	  if (hasField) {
262	    left = { kind: 'input', label: 'field', segments: parsePathSegments(condition.field, `${where} field`) };
263	  } else {
264	    left = {
265	      kind: 'output', label: 'outputField',
266	      ref: compileOutputReference(condition.outputField, nodes, `${where} outputField`),
267	    };
268	  }
269	
270	  if (condition.operator === 'exists') {
271	    const unexpected = presentComparisonKeys.filter(key =>
272	      key === 'value' || key === 'valueField' || key === 'valueOutputField');
273	    if (unexpected.length > 0) {
274	      throw new Error(`${where}: exists only takes field and operator (outputField may name the left side)`);
275	    }
276	    return { kind: 'comparison', operator: 'exists', left };
277	  }
278	
279	  const hasValue = Object.hasOwn(condition, 'value');
280	  const hasValueField = Object.hasOwn(condition, 'valueField');
281	  const hasValueOutput = Object.hasOwn(condition, 'valueOutputField');
282	  const rightCount = [hasValue, hasValueField, hasValueOutput].filter(Boolean).length;
283	  if (rightCount !== 1) {
284	    throw new Error(`${where}: condition must specify exactly one of value or valueField (or valueOutputField)`);
285	  }
286	
287	  let right;
288	  if (hasValue) {
289	    if (!isComparableConstant(condition.value)) {
290	      throw new Error(`${where}: value must be a string, finite number, boolean or null`);
291	    }
292	    right = { kind: 'constant', label: 'value', value: condition.value };
293	    if (condition.operator !== 'eq') {
294	      const numericValue = toComparableNumber(condition.value);
295	      if (numericValue === null) {
296	        throw new Error(`${where}: value for ${condition.operator} must convert to a finite number`);
297	      }
298	      right.numericValue = numericValue;
299	    }
300	  } else if (hasValueField) {
301	    if (typeof condition.valueField !== 'string') {
302	      throw new Error(`${where} valueField: path must be a non-empty string`);
303	    }
304	    right = {
305	      kind: 'input', label: 'valueField',
306	      segments: parsePathSegments(condition.valueField, `${where} valueField`),
307	    };
308	  } else {
309	    right = {
310	      kind: 'output', label: 'valueOutputField',
311	      ref: compileOutputReference(condition.valueOutputField, nodes, `${where} valueOutputField`),
312	    };
313	  }
314	
315	  return { kind: 'comparison', operator: condition.operator, left, right };
316	}
317	
318	// The normalized outgoing edges (next / then+else / none for end) of the node
319	// objects of the most recent compile pass that ran to completion — the one
320	// place branch destinations are read at edge-traversal time. A condition
321	// node's two exits are stored and read as ONE pair ([then, else]), so the
322	// target chosen for either result is always an exit the same successful
323	// validation accepted together with its sibling; the rule protects then and
324	// else alike, never just then. Unlike the form rules, condition trees, action
325	// bindings and dependency lists (each captured per run in a fresh map),
326	// successors are read here lazily when a node actually completes (or, for a
327	// condition, the moment its pinned expression is evaluated), which is the
328	// existing behavior a successful validation keeps: after a fully successful
329	// validateWorkflow (or the validation pass an execution entry makes at its
330	// own start), a run parked on a pending business operation that has not left
331	// a node yet uses the newly accepted successors, and a new run started from
332	// the edited definition uses them too.
333	//
334	// Publication is all-or-nothing per pass: compileWorkflow normalizes
335	// successors into a pass-local map and only publishes it here AFTER every
336	// node and every whole-definition check (the single-end rule and cycle
337	// detection included) has passed. A pass rejected on a node examined later,
338	// or by the cycle check that runs last — even for an edge on an untaken
339	// branch or an entry-unreachable node — never replaces any entry: the
340	// relations of the most recent SUCCESSFUL validation survive, so a parked
341	// run cannot be rerouted by an edit the caller never got accepted, and a
342	// later restore of the definition needs no second validation. Keyed by node
343	// object, independent passes over distinct definitions never interfere.
344	const successorTargets = new WeakMap();
345	
346	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
347	const DEFAULT_RETRY = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
348	
349	function isIntegerIn(value, min, max) {
350	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
351	}
352	
353	// A retry block is either absent (one attempt, no waiting) or present with all
354	// four parameters together, each within the same ranges the engine enforces
355	// for business action retries and compensation retries alike.
356	function compileRetry(config, label) {
357	  if (!isUsableObject(config)) {
358	    throw new Error(`${label}: retry must be an object`);
359	  }
360	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
361	  if (missing.length > 0) {
362	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
363	  }
364	  if (!isIntegerIn(config.attempts, 1, 10)) {
365	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
366	  }
367	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
368	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
369	  }
370	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
371	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
372	  }
373	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
374	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
375	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
376	  }
377	  if (config.maxDelayMs < config.initialDelayMs) {
378	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
379	  }
380	  return {
381	    attempts: config.attempts,
382	    initialDelayMs: config.initialDelayMs,
383	    backoffFactor: config.backoffFactor,
384	    maxDelayMs: config.maxDelayMs,
385	  };
386	}
387	
388	// An action node either keeps the legacy `message` behavior, names a business
389	// operation the caller supplies at run time, and/or declares a compensation
390	// operation that undoes its business effect. Both retry blocks are optional
391	// and, absent, mean exactly one attempt with no waiting.
392	function compileAction(node) {
393	  let name = null;
394	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
395	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
396	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
397	    }
398	    name = node.operation;
399	  }
400	
401	  let retry = { ...DEFAULT_RETRY };
402	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
403	    if (!name) {
404	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
405	    }
406	    retry = compileRetry(node.retry, `action node ${node.id}`);
407	  }
408	
409	  let compensation = null;
410	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
411	    if (!isUsableObject(node.compensation)) {
412	      throw new Error(`action node ${node.id}: compensation must be an object`);
413	    }
414	    if (!name) {
415	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
416	    }
417	    const config = node.compensation;
418	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
419	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
420	    }
421	    let compRetry = { ...DEFAULT_RETRY };
422	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
423	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
424	    }
425	    compensation = { name: config.operation, retry: compRetry };
426	  }
427	
428	  // A legacy message action (no operation) is validated through the single
429	  // configured-value gate (assertConfiguredCopy below) — the same rule, with
430	  // action-specific wording, that end-node results use — covering every
431	  // message action including ones on untaken branches and entry-unreachable
432	  // ones. An action that names an operation ignores its message entirely, so
433	  // an unused uncloneable or shared-memory message is never rejected for it.
434	  // The gate only proves the message was safe as it was then; the same rule
435	  // is re-enforced at the action's own execution moment by readConfiguredCopy.
436	  if (name === null) {
437	    assertConfiguredCopy(node, 'message', ACTION_MESSAGE_COPY_ERRORS);
438	  }
439	
440	  return { name, retry, compensation };
441	}
442	
443	// The two failure kinds a node-configured value can produce, shared by
444	// definition validation (assertConfiguredCopy below) and the execution-time
445	// capture (readConfiguredCopy below): the value cannot be structured-cloned at
446	// all, or it clones but the clone retains shared memory. Uncloneability takes
447	// precedence when a value carries both, at both moments. Each node kind keeps
448	// its own wording — an action's message and an end node's result fail with the
449	// node-specific text the entries already exposed — and its own default for a
450	// value that is absent, undefined or null (action:<node id> for a legacy
451	// message; null for an end result), while "", 0 and false pass through
452	// untouched for both.
453	const ACTION_MESSAGE_COPY_ERRORS = {
454	  uncloneable: nodeId =>
455	    `action node ${nodeId}: message must be a structured-cloneable value (objects and arrays must not contain functions)`,
456	  sharedMemory: nodeId =>
457	    `action node ${nodeId}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`,
458	};
459	const END_RESULT_COPY_ERRORS = {
460	  uncloneable: nodeId =>
461	    `end node ${nodeId}: result must be a structured-cloneable value (objects and arrays must not contain functions)`,
462	  sharedMemory: nodeId =>
463	    `end node ${nodeId}: result contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this end result is not supported`,
464	};
465	
466	// The single independent-copy rule for a value a node configures — a legacy
467	// action's `message` and an end node's `result` both go through here, so the
468	// cloneability and retained-shared-memory rules are maintained in exactly one
469	// place and the two node kinds can never drift apart. It is invoked at two
470	// moments, and each moment keeps its original root-read protocol:
471	//
472	//  1. At validation time (assertConfiguredCopy), for every such node in the
473	//     definition — including nodes on untaken branches and nodes the entry
474	//     cannot reach — so a statically invalid value is rejected before any
475	//     node, business operation or compensation can run. An absent own
476	//     property is not read at all; the gate performs the first root read and
477	//     only an own, defined value reaches the clone, which performs the root's
478	//     second read itself (a throwing root accessor propagates from the gate
479	//     exactly as before).
480	//  2. At the node's own execution moment (readConfiguredCopy), against the
481	//     value actually about to be saved: the root is read exactly once and the
482	//     value that read produced is cloned, so validation cannot pin the result
483	//     — an enumerable getter's later answer and a preceding business
484	//     operation's or another activated branch's mutation are both captured.
485	//
486	// At either moment every nested enumerable accessor is read only by
487	// structuredClone's own read — there is no separate inspection pass over the
488	// original, so a getter's return order is never disturbed and the value the
489	// clone's read produced is both what is judged and what is saved (a legal
490	// value whose getter answers with a different ordinary value at execution
491	// time records that fresh value rather than the stale validation-time one). A
492	// root getter that throws on execution's single read, a nested getter that
493	// throws while the clone reads it, and a value that cannot be cloned at all
494	// (a bare function) all surface as the same uncloneable error.
495	//
496	// The copy itself is produced by independentCopy — the one clone-then-judge
497	// rule every saved value in this engine goes through (see its comment for why
498	// cloning must precede the shared-memory traversal and why uncloneability
499	// takes precedence). Only the wording of the failure is node-specific here.
500	//
501	// Any failure is thrown as an ordinary Error naming the node (errors[kind])
502	// rather than recorded as a run status: the synchronous entry propagates it
