2244	// their own fields, never in the regular node trace.
2245	async function withCompensation(result, state, operations) {
2246	  const outcome = await compensateRun(state, operations);
2247	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
2248	  result.compensationAttempts = outcome.attempts;
2249	  return result;
2250	}
2251	
2252	// The cancelled terminal shape: the run stops where it is, keeps the
2253	// context, trace and attempt records produced so far, and never carries a
2254	// success result. Compensation for already-succeeded actions is attached by
2255	// withCompensation under the usual rules.
2256	function cancelledResult(state) {
2257	  return {
2258	    status: 'cancelled',
2259	    context: state.context,
2260	    trace: state.trace,
2261	    actionAttempts: state.actionAttempts,
2262	  };
2263	}
