2265	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
2266	  const signal = resolveRunSignal(options);
2267	  const { nodes, formRules, conditionRules, actionBindings, dependencies } = compileWorkflow(workflow);
2268	  verifyOperations(nodes, operations, actionBindings);
2269	
2270	  const state = createRunState(nodes, workflow, input, formRules, conditionRules, actionBindings, dependencies);
2271	
2272	  // A signal that is already aborted stops the run before the first node —
2273	  // but only after the definition and the operation registrations above have
2274	  // been checked. Nothing executes and nothing is compensated.
2275	  if (signal && signal.aborted) {
2276	    return withCompensation(cancelledResult(state), state, operations);
2277	  }
2278	
2279	  for (;;) {
2280	    // Once the signal fires, no new regular node runs and no new business
2281	    // action attempt starts; the run ends cancelled with whatever state it
2282	    // reached, even if an end node was already visited on another branch.
2283	    if (signal && signal.aborted) {
2284	      return withCompensation(cancelledResult(state), state, operations);
2285	    }
2286	
2287	    const step = advanceSchedule(state);
2288	
2289	    if (step.kind === 'blocked') {
2290	      // Unmet dependencies end the run; successful compensable actions are
2291	      // rolled back even though an end node may already have been reached.
2292	      return withCompensation({
2293	        status: 'blocked', context: state.context, trace: state.trace,
2294	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
2295	      }, state, operations);
2296	    }
2297	    if (step.kind === 'completed') {
2298	      // A completed run never invokes compensation.
2299	      return {
2300	        status: 'completed', result: state.endResult, context: state.context,
2301	        trace: state.trace, actionAttempts: state.actionAttempts,
2302	        compensationStatus: 'not_needed', compensationAttempts: [],
2303	      };
2304	    }
