2307	    const ready = step.node;
2308	    if (ready.type === 'action') {
2309	      // The binding this run captured at its own start: a revalidation of the
2310	      // same node object while this run was parked compiled a fresh binding
2311	      // into a different map and cannot reach this one, so the operation
2312	      // invoked, the retry budget and the compensation configuration are
2313	      // exactly the ones this run's start-time validation accepted.
