Design:

```js
// The per-entry rules every node-relation list (a successor array, a
// dependsOn list) shares: each entry must be a node id string, must not
// repeat an earlier entry, and must name a node in this definition. The
// wording of each failure is relation-specific (`wording`), and a relation
// may add its own per-entry rule after the common ones via `checkEntry`
// (dependencies use it for the no-self-dependency rule). Entries are
// checked in declaration order and the first problem is reported; the
// caller's array is never modified — the relation is returned as a fresh
// duplicate-free id list.
function checkNodeReferences(node, nodes, entries, wording, checkEntry) {
  const seen = new Set();
  for (const entry of entries) {
    if (typeof entry !== 'string') {
      throw new Error(wording.notString(node.id));
    }
    if (seen.has(entry)) {
      throw new Error(wording.duplicate(node.id, entry));
    }
    seen.add(entry);
    if (!nodes.has(entry)) {
      throw new Error(wording.unknown(node.id));
    }
    if (checkEntry) checkEntry(entry);
  }
  return [...seen];
}
```

