input.command:
node --input-type=module -e "
import { validateWorkflow } from './src/engine.js';

const base = () => ({
  id: 'w', entry: 'a',
  nodes: [
    { id: 'a', type: 'action', next: 'b' },
    { id: 'b', type: 'action', next: 'done' },
    { id: 'done', type: 'end' },
  ],
});

const cases = [
  ['next: non-string before unknown', w => { w.nodes[0].next = [42, 'ghost']; }, /entries must be node id strings/],
  ['next: duplicate before unknown', w => { w.nodes[0].next = ['b', 'b', 'ghost']; }, /duplicate destination b/],
  ['next: unknown after valid', w => { w.nodes[0].next = ['b', 'ghost']; }, /unknown destination/],
  ['deps: self after unknown (unknown first)', w => { w.nodes[1].dependsOn = ['ghost', 'b']; }, /unknown node/],
  ['deps: self first', w => { w.nodes[1].dependsOn = ['b', 'ghost']; }, /must not depend on itself/],
  ['deps: duplicate', w => { w.nodes[1].dependsOn = ['a', 'a']; }, /duplicate dependency a/],
  ['deps: entry non-empty', w => { w.nodes[0].dependsOn = ['b']; }, /entry node a must not declare dependencies/],
  ['deps: non-array', w => { w.nodes[1].dependsOn = 'a'; }, /dependsOn must be an array/],
  ['next: empty array', w => { w.nodes[0].next = []; }, /next array must not be empty/],
];

for (const [name, mutate, pattern] of cases) {
  const w = base();
  mutate(w);
  try {
    validateWorkflow(w);
    console.log('FAIL (accepted):', name);
  } catch (error) {
    console.log(pattern.test(error.message) ? 'ok  ' : 'FAIL (message: ' + error.message + ')', name);
  }
}

// Legal arrays accepted in declaration order; caller's array/object untouched.
const w = base();
w.nodes[0].next = ['b', 'done'];
w.nodes[1].dependsOn = [];
const before = JSON.stringify(w.nodes[0].next);
validateWorkflow(w);
console.log(w.nodes[0].next.length === 2 && JSON.stringify(w.nodes[0].next) === before ? 'ok   caller array untouched, order kept' : 'FAIL mutation');

// Single-string successor and omitted/undefined dependsOn still fine.
const w2 = base();
w2.nodes[1].dependsOn = undefined;
validateWorkflow(w2);
console.log('ok   undefined dependsOn accepted');
"
